def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    blocks=[]
    for r in range(h-1):
        for c in range(w-1):
            if all(grid[rr][cc]==2 for rr,cc in ((r,c),(r,c+1),(r+1,c),(r+1,c+1))):
                blocks.append((r,c))
    for r,c in blocks:
        spots={'UL':(r-1,c-1),'UR':(r-1,c+2),'LL':(r+2,c-1),'LR':(r+2,c+2)}
        vals={k:grid[rr][cc] for k,(rr,cc) in spots.items() if 0<=rr<h and 0<=cc<w}
        target={'UL':'LL','UR':'UL','LL':'LR','LR':'UR'}
        dirs={'UL':(-1,-1),'UR':(-1,1),'LL':(1,-1),'LR':(1,1)}
        for k,(rr,cc) in spots.items():
            if not (0<=rr<h and 0<=cc<w):
                continue
            color=vals.get(target[k],0)
            if not color:
                continue
            dr,dc=dirs[k]
            y,x=rr,cc
            while 0<=y<h and 0<=x<w:
                out[y][x]=color
                y+=dr; x+=dc
    return out
